<?php declare(strict_types=1); $this->layout('layouts/default', ['title'=>$title,'currentPage'=>'tags']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">ORGANIZAÇÃO</p><h2>Tags do CMS</h2><p>Gerencie termos transversais usados por páginas, projetos e artigos.</p></div></header>
<div class="studio-management-grid"><section class="studio-panel"><h3>Nova tag</h3><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><div class="studio-field"><label for="tag-name">Nome</label><input id="tag-name" name="name" minlength="2" maxlength="120" required placeholder="Ex.: estratégia"></div><button class="studio-btn primary">Criar tag</button></form></section><section><form class="studio-filter-bar" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($q) ?>" placeholder="Nome ou slug"></label><button>Buscar</button></form><div class="studio-table-wrap"><table><thead><tr><th>Nome</th><th>Slug</th><th>Conteúdos</th><th>Ações</th></tr></thead><tbody><?php if($tags===[]):?><tr><td class="studio-empty" colspan="4">Nenhuma tag encontrada.</td></tr><?php endif;?><?php foreach($tags as $tag):?><tr><td><form class="studio-inline-form" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)$tag['id'] ?>"><input name="name" value="<?= $this->e($tag['name']) ?>" required maxlength="120"><button class="studio-icon-action" aria-label="Salvar tag"><?= studio_icon('save') ?></button></form></td><td><?= $this->e($tag['slug']) ?></td><td><?= (int)$tag['usage_count'] ?></td><td><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$tag['id'] ?>"><button class="studio-icon-action danger" data-confirm="Excluir esta tag?" aria-label="Excluir tag"><?= studio_icon('trash-2') ?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></div></section>
